begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_function('public','list_organizer_event_admissions',array['uuid','text','integer','jsonb'],'bounded owner admission search exists');
\ir helpers/core_ticket_truth_lite_setup.inc
select pg_temp.record_and_fulfill('spec05search','spec05search',id,session_id) from fulfillment_orders where kind='clean';
select pg_temp.record_and_fulfill('spec05names','spec05names',id,session_id) from fulfillment_orders where kind='partial';
reset role;
set local session_replication_role=replica;
update public.orders set buyer_name='Alex Chen',buyer_email=case when id=(select id from fulfillment_orders where kind='clean') then 'alex-one@example.invalid' else 'alex-two@example.invalid' end where paid_at is not null;
set local session_replication_role=origin;
set local role authenticated;
select is(jsonb_array_length(public.list_organizer_event_admissions('a6200000-0000-4000-8000-000000000001','alex')->'admissions'),6,'duplicate buyers expose all six individual tickets');
select is(jsonb_array_length(public.list_organizer_event_admissions('a6200000-0000-4000-8000-000000000001',' ALEX-ONE@EXAMPLE.INVALID ')->'admissions'),3,'exact case-insensitive trimmed email search');
select is(jsonb_array_length(public.list_organizer_event_admissions('a6200000-0000-4000-8000-000000000001','Chen')->'admissions'),6,'partial name search');
select is(jsonb_array_length(public.list_organizer_event_admissions('a6200000-0000-4000-8000-000000000001','%_')->'admissions'),0,'wildcards are literal');
select is(jsonb_array_length(public.list_organizer_event_admissions('a6200000-0000-4000-8000-000000000001','missing')->'admissions'),0,'no matches');
select is(jsonb_array_length(public.list_organizer_event_admissions('a6200000-0000-4000-8000-000000000001','')->'admissions'),0,'blank search does not list a directory');
select throws_ok($$select public.list_organizer_event_admissions('a6200000-0000-4000-8000-000000000001',repeat('x',321))$$,'22023','Invalid admission query','search bounded');
select throws_ok($$select public.list_organizer_event_admissions('a6200000-0000-4000-8000-000000000001','alex',51)$$,'22023','Invalid admission query','page bounded');
select throws_ok($$select public.list_organizer_event_admissions('a6200000-0000-4000-8000-000000000001','alex',2,'{}')$$,'22023','Invalid admission query','malformed cursor rejected');
create temp table pages as select public.list_organizer_event_admissions('a6200000-0000-4000-8000-000000000001','alex',2) as value;
select is(jsonb_array_length((select value->'admissions' from pages)),2,'first page bounded');
create temp table page2 as select public.list_organizer_event_admissions('a6200000-0000-4000-8000-000000000001','alex',2,(select value->'nextCursor' from pages)) as value;
select isnt((select value->'admissions'->0->>'ticketId' from pages),(select value->'admissions'->0->>'ticketId' from page2),'cursor advances within multi-ticket order');
create temp table page3 as select public.list_organizer_event_admissions('a6200000-0000-4000-8000-000000000001','alex',2,(select value->'nextCursor' from page2)) as value;
select is((select count(distinct row->>'ticketId')::integer from (select value from pages union all select value from page2 union all select value from page3) p cross join lateral jsonb_array_elements(p.value->'admissions') row),6,'every ticket appears exactly once across all pages');
select is((select value->'nextCursor' from page3),'null'::jsonb,'final page ends pagination');
select is((select value->'admissions'->0->>'ticketPosition' from page2),'3','pagination retains order-wide ticket position');
select public.redeem_owned_ticket('a6200000-0000-4000-8000-000000000001',(select (value->'admissions'->1->>'ticketId')::uuid from pages));
select is(public.list_organizer_event_admissions('a6200000-0000-4000-8000-000000000001','alex',2)->'admissions'->1->>'status','used','search reflects canonical manual admission');
select ok(public.list_organizer_event_admissions('a6200000-0000-4000-8000-000000000001','alex',2)->'admissions'->1->>'usedAt' is not null,'search preserves server check-in timestamp');
select is((select value->'admissions'->0->>'ticketPosition' from pages),'1','ticket position follows existing order detail');
select is((select value->'admissions'->0->>'ticketTotal' from pages),'3','individual row contains group total');
select ok(not((select value::text from pages) ~ 'credential|stripe_|confirmation_token'),'read has no admission or provider secrets');
select ok(not has_table_privilege('authenticated','public.tickets','select'),'browser cannot read ticket base table');
select ok(not has_function_privilege('anon','public.list_organizer_event_admissions(uuid,text,integer,jsonb)','execute'),'anonymous denied');
reset role;
select set_config('request.jwt.claim.sub','a6100000-0000-4000-8000-000000000002',true);
set local role authenticated;
select throws_ok($$select public.list_organizer_event_admissions('a6200000-0000-4000-8000-000000000001','alex')$$,'42501','Event unavailable','foreign owner denied');
select * from finish();
rollback;
